def merge_agent_state(
    parent: AgentState,
    child: AgentState,
    *,
    max_records: int,
    baseline_fingerprints: Optional[set[str]] = None,
) -> dict[str, str]:
    """Merge child additions and rewrite every evidence reference."""

    if parent is child:
        return {}

    id_map: dict[str, str] = {}
    parent_by_fingerprint = {
        item.fingerprint: item for item in parent.evidence if item.fingerprint
    }
    reference_map = {
        item.id: parent_by_fingerprint[item.fingerprint].id
        for item in child.evidence
        if item.fingerprint in parent_by_fingerprint
    }
    candidate_by_fingerprint = {
        item.fingerprint: item
        for item in child.evidence
        if item.fingerprint and item.fingerprint not in parent_by_fingerprint
    }
    kept = _select_evidence(
        list(candidate_by_fingerprint.values()),
        child,
        max_records,
    )
    child_referenced = {
        evidence_id
        for claim in child.verified_claims
        for evidence_id in claim.evidence_ids
    }
    child_referenced.update(
        fact.evidence_id for fact in child.pinned_facts if fact.evidence_id
    )
    protected_parent_ids = {
        reference_map[evidence_id]
        for evidence_id in child_referenced
        if evidence_id in reference_map
    }
    kept = kept[
        : _reserve_evidence_capacity(
            parent,
            len(kept),
            protected_ids=protected_parent_ids,
        )
    ]

    for item in kept:
        parent.evidence_seq += 1
        new_id = f"e{parent.evidence_seq:03d}"
        record = copy.deepcopy(item)
        record.id = new_id
        parent.evidence.append(record)
        parent_by_fingerprint[item.fingerprint] = record
        id_map[item.id] = new_id
        reference_map[item.id] = new_id

    for item in child.evidence:
        if item.fingerprint in parent_by_fingerprint:
            reference_map[item.id] = parent_by_fingerprint[item.fingerprint].id

    child_fingerprints = {
        item.id: item.fingerprint for item in child.evidence if item.fingerprint
    }
    for old_id, parent_id in reference_map.items():
        contributed_same_id = bool(
            baseline_fingerprints is not None
            and child_fingerprints.get(old_id)
            and child_fingerprints[old_id] not in baseline_fingerprints
        )
        if old_id != parent_id or contributed_same_id:
            id_map.setdefault(old_id, parent_id)

    for item in kept:
        parent_record = parent.get_evidence(id_map[item.id])
        if parent_record is None or not parent_record.duplicate_of:
            continue
        parent_record.duplicate_of = reference_map.get(
            parent_record.duplicate_of,
            "",
        )
        if parent_record.duplicate_of == parent_record.id:
            parent_record.duplicate_of = ""

    seen_claims = {claim.claim for claim in parent.verified_claims}
    for claim in child.verified_claims:
        if claim.claim in seen_claims:
            continue
        copied = copy.deepcopy(claim)
        parent.claim_seq += 1
        copied.id = f"c{parent.claim_seq:03d}"
        copied.evidence_ids = [
            reference_map[evidence_id]
            for evidence_id in claim.evidence_ids
            if evidence_id in reference_map
        ]
        parent.verified_claims.append(copied)
        seen_claims.add(claim.claim)

    seen_pins = {fact.text for fact in parent.pinned_facts}
    for fact in child.pinned_facts:
        if fact.text in seen_pins:
            continue
        copied = copy.deepcopy(fact)
        copied.evidence_id = reference_map.get(copied.evidence_id, "")
        parent.pinned_facts.append(copied)
        seen_pins.add(fact.text)

    seen_signals = {
        (signal.kind, signal.detail) for signal in parent.progress_signals
    }
    for signal in child.progress_signals:
        key = (signal.kind, signal.detail)
        if key in seen_signals:
            continue
        copied = copy.deepcopy(signal)
        copied.evidence_id = reference_map.get(copied.evidence_id, "")
        parent.progress_signals.append(copied)
        seen_signals.add(key)

    for tool_call in child.tool_calls:
        copied = copy.deepcopy(tool_call)
        copied.evidence_id = reference_map.get(copied.evidence_id, "")
        if copied not in parent.tool_calls:
            parent.tool_calls.append(copied)
    for step in child.steps:
        if step not in parent.steps:
            parent.steps.append(copy.deepcopy(step))
    parent.pending_questions.extend(
        question
        for question in child.pending_questions
        if question not in parent.pending_questions
    )
    _enforce_auxiliary_capacity(parent)
    return id_map

def to_prompt_summary(self, *, max_evidence: int = 12, max_steps: int = 10) -> str:
        """A bounded memory block for the model-led solver."""

        sections = [
            f"Goal: {self.goal or '(unset)'}",
            f"Origin: {self.origin or '(unset)'}",
        ]
        digest = getattr(self, "context_digest", None)
        if digest and digest.summary:
            sections.append(f"\nContext digest:\n{clip_text(digest.summary, 1800)}")
        elif self.compact_summary:
            sections.append(f"\nManual compact summary:\n{clip_text(self.compact_summary, 1800)}")
        if self.verified_claims:
            sections.append("\nVerified claims:")
            sections.extend(
                f"- {claim.id}: {one_line(claim.claim, 260)} "
                f"(evidence: {', '.join(claim.evidence_ids) or 'none'})"
                for claim in self.verified_claims[-8:]
            )
        if self.pinned_facts:
            sections.append("\nHigh-signal pinned facts:")
            sections.extend(
                f"- {fact.text}" + (f" ({fact.evidence_id})" if fact.evidence_id else "")
                for fact in self.pinned_facts[-16:]
            )
        degraded = [item for item in self.tool_health.values() if item.status == "degraded"]
        if degraded:
            sections.append("\nTool health:")
            sections.extend(
                f"- {item.tool}: degraded, failures={item.consecutive_failures}, "
                f"last={item.last_error or 'unknown'}"
                for item in sorted(degraded, key=lambda x: x.tool)[-8:]
            )
        if self.correction_hints:
            sections.append("\nDiagnostic notes (optional, not instructions):")
            sections.extend(f"- {item}" for item in self.correction_hints[-6:])
        if self.progress_signals:
            sections.append("\nRecent progress signals:")
            sections.extend(
                f"- {signal.kind}: {signal.detail}"
                + (f" ({signal.evidence_id})" if signal.evidence_id else "")
                for signal in self.progress_signals[-6:]
            )
        if self.completion_rejections:
            sections.append("\nEvidence-gate reminders:")
            sections.extend(f"- {item}" for item in self.completion_rejections[-4:])
        if self.steps:
            sections.append("\nRecent agent steps:")
            sections.extend(
                f"- #{step.index} reason={step.reason or '(not stated)'} "
                f"finding={step.observation or '(none)'} "
                f"tools={', '.join(step.tool_calls) or 'none'}"
                for step in self.steps[-max_steps:]
            )
        if self.evidence:
            sections.append("\nRecent evidence:")
            for item in self.evidence[-max_evidence:]:
                sections.append(
                    f"- {item.id} tool={item.tool} status={item.status} "
                    f"summary={item.summary} raw={item.size} chars"
                    + (f" same_as={item.duplicate_of}" if item.duplicate_of else "")
                    + f" hash={item.content_hash or item.fingerprint}"
                    + ("; use evidence_view/evidence_search for raw/chunks" if item.truncated else "")
                )
        else:
            sections.append("\nRecent evidence: none yet")
        call_summary = self.tool_call_summary(12)
        if call_summary:
            sections.append("\nRecent tool calls:")
            sections.append(call_summary)
        hint = self.repeated_call_hint()
        if hint:
            sections.append(f"\n{hint}")
        return "\n".join(sections)

def format_evidence_search(
        self,
        query: str,
        *,
        evidence_id: str = "",
        regex: bool = False,
        context_chars: int = 180,
        limit: int = 12,
    ) -> str:
        """Search raw saved evidence and return bounded snippets with offsets."""

        pattern = str(query or "")
        if not pattern:
            return "evidence_search requires a non-empty query."
        try:
            max_hits = max(1, min(50, int(limit or 12)))
        except (TypeError, ValueError):
            max_hits = 12
        try:
            ctx = max(0, min(2000, int(context_chars or 180)))
        except (TypeError, ValueError):
            ctx = 180

        items = [self.get_evidence(evidence_id)] if evidence_id else list(self.evidence)
        records = [item for item in items if item is not None]
        hits: list[str] = []
        compiled: re.Pattern[str] | None = None
        if regex:
            try:
                compiled = re.compile(pattern, re.IGNORECASE | re.MULTILINE)
            except re.error as exc:
                return f"Invalid regex for evidence_search: {exc}"

        for item in records:
            raw = item.content or ""
            if compiled is not None:
                matches = compiled.finditer(raw)
            else:
                escaped = re.escape(pattern)
                matches = re.finditer(escaped, raw, re.IGNORECASE)
            for match in matches:
                start = max(0, match.start() - ctx)
                end = min(len(raw), match.end() + ctx)
                snippet = raw[start:end].replace("\r\n", "\n")
                hits.append(
                    f"{item.id}@{match.start()}:{match.end()} tool={item.tool} "
                    f"status={item.status} hash={item.content_hash or item.fingerprint}\n"
                    f"{snippet}"
                )
                if len(hits) >= max_hits:
                    break
            if len(hits) >= max_hits:
                break

        if not hits:
            scope = f" in {evidence_id}" if evidence_id else ""
            return f"No raw evidence matches {pattern!r}{scope}."
        return (
            f"# evidence_search query={pattern!r} hits={len(hits)} "
            f"(context_chars={ctx})\n\n" + "\n\n---\n\n".join(hits)
        )
